def contar(texto):
    contagem = {}
    for c in texto:
        contagem[c] = contagem.get(c, 0) + 1
    return contagem

def falta(lista):
    n = len(lista) + 1
    esperado = n * (n + 1) // 2
    return esperado - sum(lista)

def sem_repetidos(lista):
    vistos = set()
    saida = []
    for item in lista:
        if item not in vistos:
            vistos.add(item)
            saida.append(item)
    return saida

def dois_somam(lista, alvo):
    vistos = {}                      # valor -> posição
    for i, n in enumerate(lista):
        falta = alvo - n
        if falta in vistos:
            return [vistos[falta], i]
        vistos[n] = i
    return []

def primeiro_unico(texto):
    contagem = {}
    for c in texto:
        contagem[c] = contagem.get(c, 0) + 1

    for c in texto:                  # 2ª passada preserva a ordem
        if contagem[c] == 1:
            return c
    return None
